# -*- coding: utf-8 -*-
"""Rust for beginners, chapters 1-5."""
import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "cd"))
from clib import *

def F(name, cap): return {"type": "figure", "image": name, "caption": cap}
R = lambda code: C(code.strip("\n"), "rust")
CHS = []

CHS.append(CH(
 "Meet Rust",
 ("Rust", []),
 ["Rust is a programming language that gives you the speed of C with strong safety checks. The compiler is strict, but it is also a patient teacher: when it refuses your code, it tells you what is wrong and often how to fix it.",
  "Rust programs are used for browsers, game engines, operating systems, command-line tools and web servers. Their big promise is that whole families of bugs, such as using memory after it is freed, are caught before the program ever runs.",
  "In this chapter you write your first program, learn what println! does, and learn how to read a compiler message. Every chapter has a lab where you run real Rust right here in the app."],
 [("Compiler", "The program that checks your code and turns it into a runnable program."),
  ("rustc", "The Rust compiler."),
  ("Cargo", "Rust's build tool and package manager."),
  ("Macro", "A name ending in ! such as println!, which expands into more code."),
  ("main", "The function where every Rust program starts."),
  ("Crate", "A Rust package: a program or a library.")],
 ["Every program starts in fn main().",
  "println! prints a line; {} is a hole for a value.",
  "Statements end with a semicolon.",
  "Compiler errors are helpful: read the line number and the message.",
  "Cargo builds and runs projects: cargo run."],
 [T("Think of the Rust compiler as a very careful editor. You hand it a manuscript. It reads every line before the book is printed. If it finds a problem, it sends the page back with notes. Once it is satisfied, the printed book (your program) is fast and reliable."),
  F("rs-compile.svg", "Source code goes through the compiler. Mistakes stop here, before the program runs."),
  T("Here is the smallest complete Rust program."),
  R('fn main() {\n    println!("Hello, world!");\n}'),
  T("Read it piece by piece. fn means function. main is the special name where the program starts. The parentheses hold inputs (none here). The curly braces hold the body. println! prints a line of text. The exclamation mark tells you it is a macro, a helper that writes code for you. The semicolon ends the statement."),
  T("Printing values uses holes. Each {} in the text is filled by the next value you list after the string."),
  R('fn main() {\n    let name = "Ferris";\n    let year = 2015;\n    println!("{} first appeared in {}", name, year);\n}'),
  T("Some values have no plain text form, such as a tuple or a list. For those you ask for the debug form with {:?}. You can also name a value inside the braces like {name}."),
  T("Real projects use Cargo. Typing cargo new hello makes a folder with a main.rs file. cargo run builds and runs it. cargo build only builds. cargo check only checks for errors, which is the fastest way to get feedback. In our lab you skip all of that: just press Run."),
  T("Now the most important skill: reading errors. Rust errors have a code such as E0382, an arrow pointing at a line and column, and often a help line. Read from the top. Fix the first error first, because later ones are often just echoes of it."),
  T("Comments start with two slashes and are ignored by the compiler. Use them to explain why, not what.")],
 [("What does the exclamation mark in println! mean?", ["It is a macro", "It is a warning", "It means not", "It is a typo"], 0, "Macros end in !."),
  ("Where does a Rust program start?", ["fn main()", "fn start()", "The first line of any file", "cargo.toml"], 0, "The special main function."),
  ("What does {} do inside println!?", ["It is a hole filled with a value", "It ends the line", "It starts a block", "Nothing"], 0, "Values follow the string."),
  ("Which command checks for errors fastest?", ["cargo check", "cargo run", "cargo new", "cargo clean"], 0, "No program is produced."),
  ("When the compiler shows several errors, what should you fix first?", ["The first one", "The last one", "A random one", "None"], 0, "Later errors may be echoes.")],
 [("Rust's promise", "Fast like C, safe because the compiler checks"), ("println!", "Prints a line; {} holes take values"), ("{:?}", "Debug print for lists, tuples, structs"), ("cargo run", "Build and run a project")],
 [MATCH("Match the tool", "Pair each name with its job.", [("rustc", "the compiler"), ("Cargo", "build tool and package manager"), ("println!", "prints a line"), ("main", "where the program starts")]),
  FILL("First program", "Every Rust program starts in the function called {{main}}. The text {{println!}} prints a line. Statements end with a {{semicolon}}. The command {{cargo}} run builds and runs a project."),
  ORDER("From idea to output", "Put the steps in order.", ["Write code in main.rs", "The compiler checks it", "A program is produced", "You run the program"])]))

CHS.append(CH(
 "Variables, types and values",
 ("Variables", []),
 ["A variable is a named box that holds a value. In Rust the boxes are locked by default: you must say mut if you want to change one. This one choice makes programs easier to reason about.",
  "Every value has a type, which tells Rust how much memory it takes and what you may do with it. Rust usually works out the type for you, but it never silently turns one type into another.",
  "You will learn let, mut, shadowing, whole numbers, decimals, booleans, characters, tuples and arrays, and what happens when a number gets too big."],
 [("let", "Creates a variable."), ("mut", "Makes a variable changeable."), ("Shadowing", "Declaring a new variable with the same name, hiding the old one."), ("Type", "What kind of value something is, such as i32 or bool."), ("Tuple", "A fixed group of values of possibly different types."), ("Overflow", "A number going past the largest value its type can hold.")],
 ["let makes a fixed variable; let mut makes a changeable one.", "Shadowing makes a new variable and can change the type.", "No automatic conversion: use as.", "Integer types have fixed ranges; overflow panics.", "Tuples group mixed values; arrays hold same-typed values."],
 [T("Imagine labelled boxes on a shelf. let x = 5; puts the number 5 in a box labelled x and then locks the box. Try x = 6 and the compiler says you cannot assign twice to an immutable variable. If you want to change it, you say let mut x = 5;."),
  F("rs-boxes.svg", "A locked box, a changeable box, and shadowing, which makes a new box with the same name."),
  R('fn main() {\n    let mut count = 0;\n    count += 1;\n    println!("{}", count);\n}'),
  T("Why lock by default? When you read a program, a locked variable cannot change behind your back. You only need to look at where it was created. Changeable variables are marked, so you know where to be careful."),
  T("Shadowing is different from mut. It makes a brand new variable that reuses the name. Because it is new, it can even have a different type, which is handy for converting text to a number."),
  R('fn main() {\n    let n = "42";\n    let n: i32 = n.parse().unwrap();\n    println!("{}", n + 1);\n}'),
  T("Types. The whole-number types are named by sign and size: i8, i16, i32, i64 (signed, can be negative) and u8, u16, u32, u64 (unsigned, zero or more). usize is used for sizes and positions. The default for a plain number is i32. Decimals are f64 by default. Then there are bool (true or false) and char (one Unicode character, in single quotes)."),
  F("rs-types.svg", "Each integer type has a fixed range. Going past it is overflow."),
  T("Rust will not mix types behind your back. An i32 times an f64 is an error, because it is unclear which type the answer should be. You choose, using as: a as f64 turns the integer into a decimal first."),
  T("Overflow. A u8 holds 0 to 255. Adding 10 to 250 would give 260, which does not fit. In a debug build Rust panics, which means the program stops with a message. If you want the answer to stop at the maximum, use saturating_add. If you want it to wrap around, use wrapping_add. If you want to find out whether it fit, use checked_add, which returns an Option."),
  T("Compound types. A tuple groups values: let p = (3, 4.5, true). You reach inside with a dot and a position, p.0. An array holds several values of the same type and a fixed length: let a = [1, 2, 3]. Index with a[0]. Going past the end is a panic, never a quiet bug.")],
 [("What does let x = 5; followed by x = 6; do?", ["A compile error", "Sets x to 6", "Sets x to 11", "Nothing"], 0, "The box is locked."),
  ("How do you make a variable changeable?", ["let mut", "let var", "change", "let !"], 0, "mut."),
  ("What is shadowing?", ["Declaring a new variable with the same name", "Hiding a file", "Making a variable private", "A kind of loop"], 0, "A new box, same label."),
  ("What is the range of a u8?", ["0 to 255", "-128 to 127", "0 to 65535", "Any number"], 0, "8 bits, unsigned."),
  ("Which method stops at the maximum instead of overflowing?", ["saturating_add", "wrapping_add", "checked_add", "plus"], 0, "Saturate.")],
 [("let", "Locked by default"), ("let mut", "Changeable"), ("as", "Explicit conversion"), ("saturating / wrapping / checked", "Three safe ways to add")],
 [MATCH("Match the type", "Pair each type with its use.", [("i32", "default whole number"), ("f64", "default decimal"), ("bool", "true or false"), ("char", "one Unicode character")]),
  FILL("Locked boxes", "A plain let makes the variable {{immutable}}. Add {{mut}} to change it. A second let with the same name is {{shadowing}}. Convert between number types with {{as}}."),
  ORDER("Make 255 safely", "Put these steps in order to add safely to a u8.", ["Pick the type u8", "Choose saturating_add", "Add 10 to 250", "Print 255"])]))

CHS.append(CH(
 "Functions and control flow",
 ("Control flow", []),
 ["Programs make decisions and repeat things. Rust has if, match (later), and three kinds of loops. In Rust, if and blocks are expressions, which means they produce values.",
  "Functions give names to pieces of work. Their parameters must have types, and the return type comes after an arrow.",
  "The last line of a block without a semicolon is the value of the block. This is the most surprising habit for newcomers, and the most useful once you get used to it."],
 [("Function", "A named piece of reusable code."), ("Parameter", "An input to a function, with a type."), ("Expression", "Code that produces a value."), ("Statement", "Code that does something but gives no value."), ("Range", "A sequence like 1..=5."), ("Loop", "Code that repeats.")],
 ["Functions need typed parameters and an arrow for the return type.", "The last expression without a semicolon is the return value.", "if is an expression and needs a bool condition.", "for iterates a range or collection; while checks a condition; loop runs until break.", "break can carry a value out of a loop."],
 [T("Start with functions. A function is a named recipe. You give it ingredients (parameters), and it hands back a dish (the return value)."),
  R('fn square(n: i32) -> i32 {\n    n * n\n}\n\nfn main() {\n    println!("{}", square(7));\n}'),
  T("Look closely at square. There is no return word and no semicolon after n * n. That is on purpose. A block ends with its last expression, and that expression is the value. If you add a semicolon, you turn it into a statement, the block gives nothing, and the compiler complains that it expected an i32. You can still write return n * n; when you want to leave early."),
  T("Conditions. if checks a true-or-false value. Unlike some languages, Rust never treats numbers as truthy, so if n is an error but if n > 0 is fine."),
  R('fn main() {\n    let n = 7;\n    let kind = if n % 2 == 0 { "even" } else { "odd" };\n    println!("{} is {}", n, kind);\n}'),
  T("Because if is an expression, both branches must give the same type. That is why the example above can store the result straight into kind."),
  F("rs-loops.svg", "The four basic shapes of control flow."),
  T("Loops. for i in 1..=5 visits 1, 2, 3, 4, 5 (the equals sign includes the end; 1..5 stops before 5). while n < 10 repeats while the condition is true. loop repeats forever until you break, and break can hand back a value."),
  R('fn main() {\n    let mut p = 1;\n    let first = loop {\n        p *= 2;\n        if p > 1000 {\n            break p;\n        }\n    };\n    println!("{}", first);\n}'),
  T("continue skips to the next round. Loops can be given labels to break out of a nested loop, but you will rarely need that early on."),
  T("Put it together with FizzBuzz: count from 1 to 15, printing Fizz for multiples of 3, Buzz for 5, and FizzBuzz for both. The only trick is to test the combined case first.")],
 [("How do you return a value from a function without return?", ["End with an expression and no semicolon", "Use say", "Add two semicolons", "You cannot"], 0, "The last expression is the value."),
  ("What does 1..=5 include?", ["1 to 5", "1 to 4", "2 to 5", "Only 5"], 0, "The equals sign includes the end."),
  ("Can if use a number as its condition?", ["No, it needs a bool", "Yes, zero is false", "Yes, always", "Only in loops"], 0, "Rust has no truthy numbers."),
  ("How can a loop produce a value?", ["break value;", "return in main", "It cannot", "continue"], 0, "break p;"),
  ("What happens if you add a semicolon after the last expression of a function returning i32?", ["Compile error", "Nothing changes", "It returns 0", "It prints it"], 0, "The block then gives ().")],
 [("Function", "fn name(x: T) -> U"), ("Last expression", "No semicolon: it is the value"), ("..=", "Range including the end"), ("loop + break value", "Repeat and hand something out")],
 [MATCH("Match the loop", "Pair each loop with its use.", [("for", "visit each item"), ("while", "repeat while a condition holds"), ("loop", "repeat until break"), ("continue", "skip to the next round")]),
  FILL("Functions", "A function starts with {{fn}}. Parameters need {{types}}. The return type follows an {{arrow}}. The value comes from the last {{expression}} without a semicolon."),
  ORDER("Write a function", "Order these steps.", ["Choose a name", "List typed parameters", "Write the return type", "Write the body ending in an expression"])]))

CHS.append(CH(
 "Ownership: who owns the data?",
 ("Ownership", []),
 ["Ownership is the idea that makes Rust different. Every value has exactly one owner. When the owner goes out of scope, the value is cleaned up. You never free memory by hand, and you never forget to.",
  "Assigning or passing a value to another variable moves ownership. The old variable can no longer be used. Simple types like numbers are copied instead.",
  "The compiler checks all of this before the program runs, which is why Rust programs can be both fast and safe."],
 [("Owner", "The variable responsible for a value."), ("Move", "Transferring ownership; the old variable is no longer valid."), ("Copy", "Types that are duplicated instead of moved, such as integers."), ("Clone", "An explicit deep copy made with .clone()."), ("Drop", "Cleanup that runs when an owner goes out of scope."), ("Heap", "Memory for data whose size can change, such as a String.")],
 ["One value, one owner.", "Assigning a String moves it; numbers are copied.", "Use .clone() when you really want a second copy.", "Values are dropped when the owner leaves scope, in reverse order.", "Error E0382 means you used a moved value."],
 [T("Picture a library book. Only one person can have it checked out at a time. If you hand it to a friend, you do not have it any more. That is a move. If you photocopy the book first, you both have one. That is clone."),
  T("First, where data lives. Small fixed-size values such as numbers sit on the stack, a fast tidy pile. Things that can grow, like a String, keep a small handle on the stack with a pointer, length and capacity, and the real characters on the heap."),
  F("rs-stackheap.svg", "A String is a stack handle that owns bytes on the heap."),
  R('fn main() {\n    let s1 = String::from("hello");\n    let s2 = s1;\n    println!("{}", s2);\n}'),
  T("After let s2 = s1, the handle was copied to s2 and s1 gave up ownership. If both kept it, they would each try to free the same heap bytes when they left scope, which is a classic bug. Rust avoids it by making only one of them valid. If you then print s1, you get the error borrow of moved value."),
  F("rs-move.svg", "A move: s2 now owns the data and s1 is dead."),
  T("Numbers are different. let a = 5; let b = a; copies the 5, because copying a small number is cheap and safe, so both stay valid. Types that behave this way implement a trait called Copy: integers, floats, bool, char, and tuples of Copy things."),
  T("Passing to a function also moves. If shout takes a String, calling shout(s) hands s over. Afterwards main cannot use s unless the function gives it back by returning it, or you used clone, or (next chapter) you borrowed instead."),
  R('fn shout(s: String) -> String {\n    println!("{}", s.to_uppercase());\n    s\n}\n\nfn main() {\n    let s = String::from("hi");\n    let s = shout(s);\n    println!("{}", s);\n}'),
  F("rs-scope.svg", "Values are dropped at the end of their scope, last created first."),
  T("Drop. When an owner leaves its scope, Rust calls drop on the value, freeing the heap memory. You can even write your own Drop code to print a message or close a file. The order is the reverse of creation: the last variable made is the first one cleaned up. The Ownership log under your lab output shows moves and drops as they happen."),
  T("Clone makes an independent deep copy: let t = s.clone();. It costs time and memory, so Rust makes you ask for it explicitly. A good habit: when you see E0382, first ask whether you really need a second owner, or whether a borrow (next chapter) is enough.")],
 [("How many owners can a value have?", ["One", "Two", "As many as you like", "None"], 0, "One value, one owner."),
  ("What happens to s1 after let s2 = s1; for a String?", ["It is moved and cannot be used", "Both are valid", "s1 is deleted from memory", "s1 becomes empty"], 0, "Ownership transferred."),
  ("Why can you use a after let b = a; when a is an integer?", ["Integers are Copy", "Integers are special strings", "Rust allows it by accident", "They are on the heap"], 0, "Cheap to copy."),
  ("In which order are variables dropped?", ["Reverse of creation", "Same as creation", "Random", "Alphabetical"], 0, "Last in, first out."),
  ("What does .clone() do?", ["Makes an independent deep copy", "Moves the value", "Borrows it", "Deletes it"], 0, "Explicit copy.")],
 [("Owner", "One per value"), ("Move", "Old name becomes invalid"), ("Copy", "Numbers: copied, not moved"), ("Drop", "Cleanup at end of scope, reverse order")],
 [MATCH("Match the idea", "Pair each term with its meaning.", [("Move", "ownership transferred"), ("Clone", "explicit deep copy"), ("Copy", "cheap automatic duplicate"), ("Drop", "cleanup at end of scope")]),
  FILL("Ownership rules", "Each value has one {{owner}}. Assigning a String is a {{move}}. Numbers are {{Copy}}. At the end of scope the value is {{dropped}}."),
  ORDER("Follow a move", "Order the story of let s2 = s1.", ["s1 owns the data", "The handle is copied to s2", "s1 is marked as moved", "s2 owns the data and will free it"])]))

CHS.append(CH(
 "Borrowing and references",
 ("Borrowing", []),
 ["Often you want to use a value without taking it over. You do that by borrowing: you pass a reference, written with an ampersand. The owner keeps the value, and you just look at it, or change it if the reference is mutable.",
  "The borrowing rules are short: at any moment you may have any number of shared references, or exactly one mutable reference, but never both. The compiler enforces this, which prevents data races and surprise changes.",
  "References always point at valid data. Slices are a special kind of reference to part of a string or list."],
 [("Reference", "A borrowed view of a value, written &x."), ("Shared reference", "&T: read only, many allowed."), ("Mutable reference", "&mut T: can change, only one at a time."), ("Slice", "A reference to part of a string or array."), ("Dereference", "Using * to reach the value a reference points to."), ("NLL", "Non-lexical lifetimes: a borrow ends at its last use.")],
 ["& borrows; the owner keeps ownership.", "Many readers OR one writer.", "A borrow lasts until its last use, not until the end of the block.", "&mut needs a let mut variable.", "&str is a slice: a borrowed piece of a string."],
 [T("Back to the library. Borrowing is like reading a book in the library without taking it home. Many people can read the same book at once. But if one person wants to scribble in it, nobody else can be reading at that moment."),
  R('fn length(s: &String) -> usize {\n    s.len()\n}\n\nfn main() {\n    let s = String::from("hello");\n    let n = length(&s);\n    println!("{} has {} letters", s, n);\n}'),
  T("The function asks for &String, a reference. The caller passes &s. After the call, main still owns s and can print it. No clone, no moving back and forth."),
  F("rs-borrow.svg", "Many shared readers, or one mutable writer."),
  T("To change something through a reference, both the variable and the reference must say mut: let mut s, and &mut s, and the function takes &mut String."),
  R('fn add_world(s: &mut String) {\n    s.push_str(", world");\n}\n\nfn main() {\n    let mut s = String::from("hello");\n    add_world(&mut s);\n    println!("{}", s);\n}'),
  T("The big rule again: many & or one &mut, never both at once. Why? Imagine reading a list while someone else is deleting items from it. You would see nonsense. Rust prevents that situation at compile time. The error is E0502 (reader and writer mixed) or E0499 (two writers)."),
  T("How long does a borrow last? Until the last time you use the reference. This is called non-lexical lifetimes. So you can read through a reference, finish with it, and then start a mutable borrow right after. The classic broken example takes a reference to the first item of a Vec, then pushes onto the Vec, then uses the reference. Moving the print before the push fixes it, because the reference is finished by then."),
  R('fn main() {\n    let mut v = vec![1, 2, 3];\n    let first = &v[0];\n    println!("{}", first);\n    v.push(4);\n    println!("{:?}", v);\n}'),
  T("Why does a push cause trouble? A Vec may need to move to bigger memory when it grows. A reference to the old spot would then point at nothing. By refusing the code, Rust saves you from a dangling pointer."),
  F("rs-slice.svg", "A slice is a view into part of a string."),
  T("Slices. &s[0..5] borrows the first five bytes of s. The type of a string slice is &str, and it is also the type of string literals like \"hello\". Prefer &str in function parameters, because it accepts both String borrows and literals. While a slice exists, the original cannot be changed, for the same reason as above."),
  T("A rule of thumb for choosing: pass by reference (&T) when the function only needs to look, &mut T when it must change the value, and by value (T) when the function should take over ownership, for example to store it.")],
 [("What does &s mean?", ["Borrow s without taking ownership", "Move s", "Copy s", "Delete s"], 0, "A reference."),
  ("How many mutable references to a value can be active at once?", ["One", "Two", "Unlimited", "Zero"], 0, "Exactly one."),
  ("Can you have a shared and a mutable reference alive together?", ["No", "Yes", "Only for strings", "Only in loops"], 0, "Many readers OR one writer."),
  ("When does a borrow end under NLL?", ["At its last use", "At the end of the program", "At the next line", "When the owner moves"], 0, "Last use."),
  ("What is the type of the literal \"hi\"?", ["&str", "String", "str", "char"], 0, "A string slice.")],
 [("&T", "Read-only borrow, many allowed"), ("&mut T", "Write borrow, exactly one"), ("Last use", "Where a borrow really ends"), ("&str", "Borrowed piece of text")],
 [MATCH("Match the reference", "Pair each with its rule.", [("&T", "many allowed, read only"), ("&mut T", "only one, can change"), ("Slice", "view of part of a collection"), ("Dereference", "reach the value with *")]),
  FILL("Borrowing rules", "A reference is written with {{&}}. You may have many {{shared}} references or exactly one {{mutable}} reference. A borrow ends at its {{last use}}."),
  ORDER("Fix a borrow error", "Put these lines in a working order.", ["let mut v = vec![1, 2, 3];", "let first = &v[0];", "println!(\"{}\", first);", "v.push(4);"])]))
